import numpy as np
import pandas as pd

with open('evaluations.json') as f:
    evals = json.load(f)

for e in sorted(evals, key=lambda x: x['target_dissimilarity']):
    d = {x['ingredient']: x['fraction'] for x in e['recipe']}
    print(f"Iter {e['iteration']:2d}: y={e['target_dissimilarity']:.6f} | {d}")
"}

